                { "Je rougis de l'intérieur quand passe la reliure d'une certaine mite. Antenne qui tremble. Pattes en coton. C'est grave.", fase = "jovem" },
                { "J'ai croisé cette mite près de la fenêtre. On a parlé d'humidité pendant une heure. La plus belle heure de ma vie.", fase = "jovem" },
                { "La jalousie, c'est te voir ouvrir un autre livre avant d'avoir fini le nôtre.", fase = "jovem", curta = "Jalousie : tu ouvres un autre livre avant." },
                { "J'ai glissé un mot par la fente de l'étagère. La réponse est arrivée deux jours plus tard : une miette. Je la garde encore.", fase = "jovem" },
