                { "Aujourd'hui, elle a mangé à côté de moi. Personne n'a rien dit. Le meilleur chapitre de l'année.", quando = "feliz", fase = "jovem" },
                { "L'amour sans retour a le goût du papier glacé : ça brille et ça ne nourrit pas.", quando = "triste", fase = "jovem", curta = "Amour sans retour : ça brille, ça ne nourrit pas." },
                { "Peau neuve, vieux cœur. La mue n'a rien réglé de ce qui compte.", quando = "muda", fase = "jovem" },
