                { "Je suis allée jusqu'au bout du couloir. Il y a tout un monde là-bas : un tapis qui ressemble à un désert, une plinthe qui ressemble à une côte et un chat qui ressemble à la fin de l'expédition.", fase = { "ninfa", "jovem" }, curta = "J'ai exploré le couloir. Un désert, puis un chat." },
                { "J'ai cartographié « {livro} » avec les dents : le nord, c'est la couverture, le sud, le rabat, et au milieu s'étend une mer de pages dont personne ne revient pareil." },
                { "Entre la plinthe et le tapis, il existe un passage qu'aucun humain ne connaît. Moi, si. C'est ma seule propriété.", fase = { "adulta", "ancia" }, curta = "Ma seule propriété : le passage sous la plinthe." },
                { "Si j'étais {personagem}, je serais déjà loin. Mais je suis une mite, et le monde a des balais à toutes ses frontières." },
                { "Il y a eu {evento}. Je l'ai noté dans mon journal de bord, c'est-à-dire la marge de la page quarante. Les grands explorateurs aussi écrivaient de travers.", curta = "Il y a eu {evento}. Noté au journal de bord." },
                { "Aujourd'hui, j'ai découvert que l'étagère a un autre côté. Personne ne m'avait prévenue. Le monde est plus grand qu'un livre, et ça donne faim.", fase = "ninfa" },
                { "J'ai prévu de traverser tout le salon jusqu'au carton de la buanderie. On dit qu'il y a de vieux journaux. On dit que personne n'en revient. On dit beaucoup de choses.", fase = "jovem" },
