                { "Je suis allée au cellier, au garage et dans une valise qui a pris l'avion. Aujourd'hui, mon plus grand voyage va de la couverture jusqu'au milieu. Ça vaut encore le coup.", fase = "ancia" },
                { "Je suis sortie de ma cachette comme on part pour {lente}. Je suis revenue avec une miette et une histoire que je raconterai plus grande qu'elle n'était." },
                { "Le plus grand danger, ce n'est pas l'inconnu. C'est le connu, chausson à la main.", fase = { "adulta", "ancia" } },
