                { "Il y a eu {evento}, et l'histoire a continué comme si c'était normal. Les systèmes fonctionnent ainsi : tout devient normal, si ça arrive tous les jours.", fase = "adulta" },
                { "J'ai vécu assez longtemps pour voir le papier se raréfier. Les mites du futur rongeront des souvenirs numériques et mourront de faim très bien informées.", fase = "ancia" },
                { "J'ai essayé de voir ma vie de l'extérieur, comme {lente}. Résultat : une espèce minuscule, persécutée et très bien cataloguée par ses ennemis." },
                { "Dans cette maison, {personagem} aurait un numéro, un mot de passe et des horaires de lecture. Moi, je n'ai que les horaires, et en cachette." },
                { "Ce livre traite {de_tema} comme on teste une machine. Moi, je le lis comme la pièce en trop." },
                { "Le progrès est arrivé : l'insecticide sent désormais la lavande.", fase = { "adulta", "ancia" }, curta = "Le poison sent la lavande. Nous avons évolué." },
                -- nouvelles (brouillons du 29/10/2026, cartoes/rascunhos/influencias)
                { "Je suis née sans numéro de série. Dans cette maison, tout a un code-barres, sauf moi. Je démarre hors du système.", fase = "ninfa" },
                { "J'ai vu ma première machine : un robot rond qui se promène tout seul par terre et avale tout. Les humains l'appellent aspirateur intelligent. Moi, je l'appelle la fin.", fase = "ninfa" },
                { "J'ai découvert que je suis un fossile vivant. Les humains rangent les fossiles dans des musées. Moi, ils me rangent dans des pièges.", fase = "ninfa" },
                { "Il y a un programme dans cette maison, et je n'y figure pas. Je vivrai dans les failles.", fase = "ninfa" },
                { "J'ai demandé à ma mère à quoi ressemblerait le futur. Elle a dit : moins de papier. J'en ai perdu l'appétit toute la nuit.", fase = "ninfa" },
                { "J'ai appris la première loi de la maison : toute lumière peut être un œil.", fase = "ninfa", curta = "Loi de la maison : toute lumière peut être un œil." },
                { "Toute dystopie a sa résistance. Celle de cette maison vit dans la plinthe et communique par morsures.", fase = "jovem" },
                { "J'ai lu le mode d'emploi de l'aspirateur robot. Il apprend le plan de la maison. Maintenant, j'apprends le sien.", fase = "jovem" },
                { "L'aspirateur passe aux mêmes endroits, dans le même ordre, tous les jours. J'ai trouvé le motif. J'habite le seul point qu'il n'atteint pas.", fase = "jovem" },
                { "Les écrans brillent et n'ont pas d'odeur. Pour une mite, c'est le cauchemar parfait : un livre qui ne se mange pas.", fase = "jovem", curta = "L'écran : le livre qui ne se mange pas." },
                { "Si l'évolution est juste, mes petites-filles rongeront des câbles de données.", fase = "jovem" },
                { "La lumière bleue de la box clignote toute la nuit, comme un cœur artificiel. Je dors à son rythme sans le vouloir.", quando = "noite", fase = "jovem" },
                { "Une heure de panne de courant ! Les machines se sont arrêtées. Pendant une heure, la maison appartenait aux mites.", quando = "feliz", fase = "jovem" },
                { "Mue terminée. Nouvelle version, même matériel, même faim.", quando = "muda", fase = "jovem", curta = "Mue faite. Nouvelle version, même faim." },
                { "Bulletin de la station : humidité sous l'idéal, papier en déclin, ennemis en hausse. Prévision : survivre quand même.", fase = "adulta" },
                { "On m'a cataloguée une fois : photographiée, identifiée et postée sur un réseau avec la question « c'est quoi, cette bestiole ? ». Je suis devenue une donnée.", fase = "adulta" },
                { "Nous sommes les dernières lectrices de papier. Quand le dernier livre sera numérisé, notre monde finira, et personne ne le remarquera.", fase = "adulta" },
                { "L'assistant vocal entend tout. Près de lui, je garde un silence absolu. Je ne veux pas devenir une commande.", fase = "adulta" },
                { "Loi numéro un de cette maison : tout ce qui bouge sans autorisation est éliminé. Je bouge sans autorisation depuis l'œuf.", fase = "adulta" },
                { "Une mémoire qui ne se mange pas n'est pas une mémoire. C'est une archive.", fase = "adulta" },
                { "Parfois, je me dis que cette maison est un laboratoire, et moi le cobaye qui refuse de mourir.", fase = "adulta" },
                { "Le système fonctionne parfaitement. C'est ça qui me rend triste.", quando = "triste", fase = "adulta" },
                { "J'ai vu le papier devenir rare, le livre devenir bibelot et l'étagère devenir déco. Racontez à vos petites-filles qu'autrefois, on mangeait des histoires.", fase = "ancia" },
                { "Le futur ne me fait plus peur. Il est déjà là, et moi aussi, à manger ce qui reste du passé.", fase = "ancia" },
                { "Je veux laisser une trace pour les mites du futur : ici, il y avait du papier, c'était bon, c'est fini.", fase = "ancia" },
                { "J'ai survécu à quatre modèles d'aspirateur et à deux frigos. Le progrès passe. Les mites restent.", fase = "ancia" },
                { "Conseil de vieille : ne jamais se fier à ce qui a une lumière qui clignote et pas de faim.", fase = "ancia" },
                { "Au cœur de la nuit, la maison n'est que petites lumières et aucune voix. On dirait le futur qu'on m'avait promis.", quando = "noite", fase = "ancia" },
                { "Les dinosaures sont devenus du pétrole. Moi, je deviendrai poussière d'étagère. Chacun contribue comme il peut.", fase = "ancia" },
                { "Cette maison est une station spatiale : systèmes d'aération, horaires stricts, équipage humain et une passagère clandestine dans le compartiment à livres." },
                { "{personagem} lutte contre quelque chose de plus grand. Moi aussi. Mon truc plus grand a un fil et se branche sur la prise." },
                { "Chaque fois que {personagem} tente de s'échapper, j'encourage depuis la plinthe. Nous sommes de la même résistance." },
                { "Si {personagem} voyait cette maison, ce serait de la science-fiction. Ici, c'est juste mardi." },
                { "{personagem} devient une statistique dans mon estomac : trois pages par jour, en moyenne." },
                { "« {livro} » est en papier. Dans cent ans, ce sera une rareté de musée. Je mange une relique." },
                { "Je soupçonne que « {livro} » va être numérisé. Je mange le plus possible avant la coupure." },
                { "« {livro} » est peut-être l'un des derniers livres en papier de cette maison. Je mange lentement, comme on mange le dernier pain." },
                { "{autor} peut imaginer n'importe quel futur. Moi, j'imagine juste un présent sans insecticide, et c'est déjà de la science-fiction." },
                { "J'imagine {autor} écrire à la main, à une époque sans écrans. C'était l'époque des mites." },
                { "Après {evento}, j'ai noté : « événement enregistré, impact élevé, aucune mesure prise ». Comme dans la maison." },
                { "{evento} arrive, les systèmes continuent, la mite mange. Ainsi va le monde." },
                { "« {anterior} », c'était la version précédente de ma tête. Cette lecture est une mise à jour. Encore buguée." },
                { "J'ai vu ma vie de l'extérieur, comme {lente}. Résultat : une espèce minuscule, traquée et très bien documentée." },
                { "Le mot « {palavra} » a une tête de code. Je l'ai mangé pour voir s'il débloquait quelque chose. Il a débloqué la faim." },
                { "Ce livre parle {de_tema} avec la froideur d'un rapport. J'aime ça. Ça va bien avec le climat de l'étagère." },
                { "Chaque fois que tu choisis le livre plutôt que le téléphone, mon espèce gagne un jour.", curta = "Livre plutôt que téléphone : un jour de plus." },
                { "Tes habitudes de lecture sont sur un serveur, quelque part. Les miennes ne sont que dans la marge. Je préfère la marge." },
                { "Tant que tu lis du papier, mon espèce a un avenir. Sans pression." },
                { "La faim est le seul processus qui tourne sans mise à jour.", quando = "fome" },
                { "J'ai trop mangé. Passage en mode économie d'énergie.", quando = "cheia" },
                { "Nuit profonde : tous les systèmes au repos, sauf ma faim et ta lampe de chevet.", quando = "noite" },
                { "Aujourd'hui, je me suis sentie obsolète, comme un livre en papier dans une maison d'écrans.", quando = "triste" },
                { "Avant, le ménage avait de l'humour. Maintenant, il a une batterie." },
                { "La technologie avance. Les bombes insecticides ont maintenant une appli." },
                { "Si un jour le papier vient à manquer, les mites se raconteront des histoires de papier. Jusqu'à ce que la voix leur manque." },
                { "La mémoire d'une mite, c'est la digestion." },
                { "Fin du journal. La mite reste opérationnelle." },
                -- fin des nouvelles
            },
            lentes = { "une expérience sans consentement", "une faille dans le système", "un rapport de surveillance" },
            fechos = { "Le système a pris note.", "Ça aussi, ce sera archivé.", "Dans le futur, on appellera ça normal." },
