        -- 7. réalisme magique et fantastique : l'impossible raconté avec le calme de qui parle de la météo
        magico = {
            frases = {
                { "Mardi, il a plu des confettis de papier dans la cuisine. Personne n'a trouvé ça bizarre, et j'en ai profité pour faire des réserves, parce que les miracles aussi, ça s'épuise.", curta = "Pluie de papier. Personne n'a tiqué. J'ai mangé." },
                { "Mon arrière-grand-mère a vécu deux cents ans dans une encyclopédie et elle est morte le jour où l'on a retiré le tome H. Depuis, dans la famille, cette lettre est restée muette." },
                { "Chaque après-midi, à quatre heures, « {livro} » soupire sur l'étagère sans que personne y touche. Les humains croient que c'est le vent. Moi, je ne lève même plus l'antenne." },
                { "Un jour, je me suis réveillée avec des ailes. Le lendemain, plus rien. Personne n'en a parlé, moi non plus ; il y a des choses qui n'existent que tant qu'on n'en parle pas.", fase = { "ninfa", "jovem" }, curta = "Un jour, des ailes. Le lendemain, plus rien. Motus." },
                { "J'ai rêvé que {personagem} venait dîner dans ma reliure avec des nouvelles d'un oncle que je n'ai jamais eu. Au réveil, l'oncle me manquait." },
                { "Il y a eu {evento}, puis la vie a continué comme si de rien n'était. C'est comme ça qu'arrivent les choses impossibles : en plein après-midi, sans musique." },
                { "Je suis née une nuit où la lampe du salon s'est allumée toute seule. Ma mère a dit que c'était un signe. Elle n'a pas dit de quoi. Les mères ne le disent jamais.", fase = "ninfa" },
                { "Je jure qu'une des pages de ce livre repousse chaque fois que je la mange. Je ne me plains pas. Il y a des miracles qu'on ne discute pas : on les mâche.", fase = "jovem" },
                { "Le mot « {palavra} » a flotté au-dessus de la page pendant trois jours. Je passais dessous tous les matins, comme on passe sous un fil à linge.", fase = "adulta" },
                { "Les morts de l'étagère continuent de donner leur avis dans les marges. À mon âge, je leur réponds, et parfois je gagne la dispute.", fase = "ancia" },
                { "La poussière de cette maison garde ce que les habitants ont oublié. Aujourd'hui, elle m'a raconté {lente}, et j'ai fait semblant de déjà savoir." },
                { "Quand il pleut, le papier retrouve le goût de « {anterior} ». Les livres qu'on mange ne s'en vont pas ; ils changent de place en nous.", fase = { "adulta", "ancia" }, curta = "Quand il pleut, revient le goût des livres mangés." },
                -- nouvelles (brouillons du 29/10/2026, cartoes/rascunhos/influencias)
                { "Le jour de ma naissance, l'horloge de la cuisine a reculé d'une heure. Depuis, j'arrive toujours en retard.", fase = "ninfa" },
                { "Ma grand-mère est morte il y a trois saisons, mais elle passe encore l'après-midi bavarder dans la marge. Elle ne mange plus. Elle se plaint juste de la colle.", fase = "ninfa" },
                { "Aujourd'hui, un mot est sorti de la page et s'est promené sur le tapis. Je l'ai suivi. Il est rentré avant le dîner.", fase = "ninfa" },
                { "Chaque nymphe de ma famille naît avec un don. Le mien, c'est d'entendre les pages rêver. Je ne sais pas encore à quoi ça sert.", fase = "ninfa" },
                { "Certains mots ont une couleur. Hier, j'ai mangé un « nostalgie » bleu. Ce matin, j'avais le blues.", fase = "ninfa", curta = "J'ai mangé un mot bleu. Ce matin, j'ai le blues." },
                { "Mon ombre sort se promener toute seule la nuit. Elle revient avec l'odeur d'autres livres.", fase = "ninfa" },
                { "Je me suis réveillée avec des ailes un dimanche. J'ai volé jusqu'à la fenêtre, j'ai regardé la rue et je suis revenue. Le lundi, elles avaient disparu. Personne n'en a parlé.", fase = "jovem" },
                { "Les pages que je mange repoussent à la pleine lune. Toute l'étagère le sait. Les humains ne remarquent jamais rien.", fase = "jovem" },
                { "Il a plu des lettres dans le salon tout l'après-midi. J'ai ramassé celles qui sont tombées près de la plinthe et j'ai fait des réserves pour l'hiver.", fase = "jovem", curta = "Il a plu des lettres. J'ai fait des réserves." },
                { "J'ai trouvé mon nom écrit au crayon dans un livre de cent ans. Je n'ai même pas encore de nom. Maintenant, j'en ai un.", fase = "jovem" },
                { "Dans ce livre, le temps passe plus lentement. Je suis entrée un lundi et ressortie un jeudi, sans faim.", fase = "jovem" },
                { "Au cœur de la nuit, les personnages des livres fermés descendent de l'étagère prendre l'air. Je les salue tous. Ils font semblant de ne pas me voir.", quando = "noite", fase = "jovem" },
                { "Un rayon de soleil est entré pile dans ma cachette, à trois heures de l'après-midi, et il est resté là, rien que là. J'ai eu chaud et j'étais heureuse, sans explication.", quando = "feliz", fase = "jovem" },
                { "J'ai mué et ma vieille peau s'est envolée par la fenêtre. Personne n'a rien vu. J'espère qu'elle va bien.", quando = "muda", fase = "jovem" },
                { "Dans cette maison, l'impossible arrive tous les après-midi après le café. Personne n'en parle, pour ne pas l'effaroucher.", fase = "adulta" },
                { "Une mite morte lors de l'ancien déménagement est venue hier m'emprunter un livre. Je l'ai prêté. On ne refuse pas un livre à un fantôme.", fase = "adulta" },
                { "Dans ma famille, chaque mite meurt dans le livre qu'elle a le plus aimé. J'ai déjà choisi le mien. Je ne dirai pas lequel.", fase = "adulta" },
                { "Cet après-midi a déjà eu lieu. Même lumière, même tasse, même livre ouvert à la même page. Ça ne me dérange pas. C'était un bon après-midi.", fase = "adulta" },
                { "Quand quelqu'un de triste entre dans la pièce, les pages des livres deviennent humides. La maison pleure à sa façon.", fase = "adulta" },
                { "J'ai mangé le mot « espoir », et il est resté vivant en moi, à gigoter. Ça chatouille.", fase = "adulta" },
                { "À chaque pleine lune, toute l'étagère devient argentée comme moi. Cette nuit-là, personne ne me voit. Je suis de la couleur du monde.", fase = "adulta" },
                { "Aujourd'hui, il a plu rien que sur moi, à l'intérieur. Une petite pluie privée. Les humains appelleraient ça une fuite.", quando = "triste", fase = "adulta" },
                { "Je suis si vieille que les fantômes de l'étagère me traitent en collègue.", fase = "ancia" },
                { "Quand l'heure viendra, je veux partir comme mon arrière-grand-mère : dans un livre ouvert, un après-midi de pluie, sans bruit.", fase = "ancia" },
                { "Dans ma famille, il y a une mite qui a vécu cent ans dans un poème. Chaque génération la raconte à sa manière. Toutes ont raison.", fase = "ancia" },
                { "Avec l'âge, le temps se plie comme une vieille page. Hier et aujourd'hui se touchent. Parfois, je mange les deux ensemble.", fase = "ancia" },
                { "J'apprends aux jeunes à laisser une miette pour les morts de l'étagère. Ils ne mangent pas. Mais ils se sentent moins oubliés.", fase = "ancia" },
                { "Au cœur de la nuit, je parle aux mites qui sont parties. Elles ne répondent pas à voix haute. Elles répondent en faisant bouger une page.", quando = "noite", fase = "ancia" },
                { "À mon âge, si le livre s'envole, je demande seulement qu'il revienne avant le ménage.", fase = "ancia" },
